import test from 'node:test';
import assert from 'node:assert/strict';
import {appendFileSync} from 'node:fs';
for (let i=0; i<1; i++) test(`case-${i}`, () => {
  appendFileSync('calls.txt', 'x');
  assert.equal(i >= 1-0 ? 2 : 1, 1, `result-${i}`);
});

